Method.Implementation:
	set tSC = $$$OK
	$$$TRACE("Inside Select prfnltype Method")
	set tPRVDR=pRequest.StringValue
    $$$TRACE("Provider ID: "_tPRVDR)
	set pResponse = ##class(IHC.ITF.DStruc.Request.CORPPRV.ListOfMdmExtraFields).%New()

	// So this get all the records
	set pRes = ##class(EnsLib.SQL.Snapshot).%New()
	set pRes.MaxRowsToGet = -1

	set tSQL1 = "SELECT CADVFA.FCILITY_ID AS FCILITY_ID, CADVFA.PRMRY_FLG As PRMRY_FLG, CADVFA.PRVDR_ID As PRVDR_ID, FACI.FCILITY_NM As FCILITY_NM, "
	set tSQL1 = tSQL1 _ " FACI.ADDR1 AS ADDR1, FACI.ADDR2 AS ADDR2, CITY.CITY_NM AS CITY, SUBSTR(FACI.ZIP_CD, 1, 5) as ZIP, SUBSTR(FACI.ZIP_CD, 6, 4) as ZIP_EXT,"
    set tSQL1 = tSQL1 _ " CONCAT (FACI.LOCAL_AREA_CD , FACI.LOCAL_PHONE_NO) as PHN, CONCAT (FACI.FAX_AREA_CD , FACI.FAX_NO) as FAX "
    set tSQL1 = tSQL1 _ " FROM CORPPRV.ADV_FACILITY_AFFILIATION CADVFA, "
    set tSQL1 = tSQL1 _ " FACILITY.FCILITY FACI, CORPPRV.CITY CITY"
    set tSQL1 = tSQL1 _ " WHERE CADVFA.FCILITY_ID = FACI.FCILITY_ID  and FACI.CITY_ID = CITY.CITY_ID"
    set tSQL1 = tSQL1 _ " AND CADVFA.PRVDR_ID = ?"


    set tSQL2 = "SELECT CADVSP.SPCLTY_ID, CSP.SPCLTY_DSC, CADVSP.PRVDR_ID, CADVSP.PRIMARY_FLG "
    set tSQL2 = tSQL2 _ " FROM CORPPRV.ADV_PRVDR_SPCLTY CADVSP, CORPPRV.SPECIALTY CSP "
    set tSQL2 = tSQL2 _ " WHERE CSP.SPCLTY_ID = CADVSP.SPCLTY_ID AND CADVSP.PRVDR_ID = ?"

    set tSQL3 = "SELECT prvdr_addr_seq,  addr_line_1_txt "
    set tSQL3 = tSQL3 _ " FROM CORPPRV.ADV_PRVDR_ADDR CADPA "
    set tSQL3 = tSQL3 _ " WHERE CADPA.PRVDR_ID = ?"

    set tSQL4 = "SELECT LANGUAGE_CD "
    set tSQL4 = tSQL4 _ " FROM CORPPRV.ADV_PROVIDER_LANGUAGE_CODE "
    set tSQL4 = tSQL4 _ " WHERE PRVDR_ID = ?"

	set ioParms=1
	set ioParms(1)=tPRVDR
	set ioParms(1,"SqlType")=3

	set list1 =  ##class(%ListOfObjects).%New()		
 	set tSC = ..Adapter.ExecuteQueryParmArray(.pRes,tSQL1,.ioParms)

	if tSC = 1
	{
		$$$TRACE("Successfully executed Query:"_tSQL1)
		IF ($ISOBJECT(pRes)&&(pRes.RowCount>0))
		{
			$$$TRACE("Retrieve data from the Response, # of rows:" _ pRes.RowCount)
			set rowNum=pRes.Next(.sc)
			WHILE (rowNum > 0)
			{
				set dataRow = ##class(IHC.ITF.DStruc.Request.CORPPRV.CorpprvFacilities).%New()

				if ($$$ISERR(sc)){
					$$$TRACE("Error Reading result set")
					set tSC=$$$ERROR("Error Reading Result set")
				}
				else{
					set dataRow.PRVDRID = pRes.Get("PRVDR_ID")
					set dataRow.FCILITYID = pRes.Get("FCILITY_ID")
					set dataRow.FACIFCILITYNM = pRes.Get("FCILITY_NM")
					set dataRow.CADVFAPRMRYFLG = pRes.Get("PRMRY_FLG")			
					set dataRow.FACAADR1 = pRes.Get("ADDR1")
					set dataRow.FACAADR2 = pRes.Get("ADDR2")
					set dataRow.FACCITY = pRes.Get("CITY")
					set dataRow.FACZIP = pRes.Get("ZIP")
					set dataRow.FACZIPEXT = pRes.Get("ZIP_EXT")
					set dataRow.FACPHN = pRes.Get("PHN")
					set dataRow.FACFAX = pRes.Get("FAX")

					DO list1.Insert(dataRow)

				}
				set rowNum=pRes.Next(.sc)

			}
			set pResponse.facList = list1
			$$$TRACE("Return Status: "_sc _", facList rowNum: " _ pResponse.facList.Count())

		}
 } else {
		$$$TRACE("Failed to execute Query:"_tSQL1)	
 }

 set list2 =  ##class(%ListOfObjects).%New()
 set tSC = ..Adapter.ExecuteQueryParmArray(.pRes,tSQL2,.ioParms)


 if tSC = 1
 {
		$$$TRACE("Successfully executed Query:"_tSQL2)
		IF ($ISOBJECT(pRes)&&(pRes.RowCount>0))
		{
			$$$TRACE("Retrieve data from the Response, # of rows:" _ pRes.RowCount)
			set rowNum=pRes.Next(.sc)
			WHILE (rowNum > 0)
			{
				set dataRow = ##class(IHC.ITF.DStruc.Request.CORPPRV.CorpprvSpecialities).%New()


				if ($$$ISERR(sc)){
					$$$TRACE("Error Reading result set")
					set tSC=$$$ERROR("Error Reading Result set")
				}
				else{
					set dataRow.PRVDRID = pRes.Get("PRVDR_ID")

					set dataRow.CADVSPSPCLTYID = pRes.Get("SPCLTY_ID")
					set dataRow.CSPSPCLTYDSC = pRes.Get("SPCLTY_DSC")  
					set dataRow.CADVSPPRIMARYFLG = pRes.Get("PRIMARY_FLG") 

					DO list2.Insert(dataRow)

				}
				set rowNum=pRes.Next(.sc)

			}
			set pResponse.specList = list2
			$$$TRACE("Return Status: "_sc _", specList rowNum: " _ pResponse.specList.Count())

		}
 } else {
		$$$TRACE("Failed to execute Query:"_tSQL2)	
 }

 set list3 =  ##class(%ListOfObjects).%New()
 set tSC = ..Adapter.ExecuteQueryParmArray(.pRes,tSQL3,.ioParms)


 if tSC = 1
 {
		$$$TRACE("Successfully executed Query:"_tSQL3)
		IF ($ISOBJECT(pRes)&&(pRes.RowCount>0))
		{
			$$$TRACE("Retrieve data from the Response, # of rows:" _ pRes.RowCount)
			set rowNum=pRes.Next(.sc)
			WHILE (rowNum > 0)
			{
				set dataRow = ##class(IHC.ITF.DStruc.Request.CORPPRV.CorpprvAddrSeqs).%New()


				if ($$$ISERR(sc)){
					$$$TRACE("Error Reading result set")
					set tSC=$$$ERROR("Error Reading Result set")
				}
				else{
					set dataRow.PRVDRID = pRes.Get("PRVDR_ID")

					set dataRow.AddrSeq = pRes.Get("prvdr_addr_seq")  
					set dataRow.AddrLine1 = pRes.Get("addr_line_1_txt") 

					DO list3.Insert(dataRow)

				}
				set rowNum=pRes.Next(.sc)

			}
			set pResponse.addrList = list3
			$$$TRACE("Return Status: "_sc _", addrList rowNum: " _ pResponse.addrList.Count())

		}
 } else {
		$$$TRACE("Failed to execute Query:"_tSQL3)	
 }

 set list4 =  ##class(%ListOfDataTypes).%New()
 set tSC = ..Adapter.ExecuteQueryParmArray(.pRes,tSQL4,.ioParms)


 if tSC = 1
 {
		$$$TRACE("Successfully executed Query:"_tSQL4)
		IF ($ISOBJECT(pRes)&&(pRes.RowCount>0))
		{
			$$$TRACE("Retrieve data from the Response, # of rows:" _ pRes.RowCount)
			set rowNum=pRes.Next(.sc)
			WHILE (rowNum > 0)
			{

				if ($$$ISERR(sc)){
					$$$TRACE("Error Reading result set")
					set tSC=$$$ERROR("Error Reading Result set")
				}
				else{
					set lang = pRes.Get("LANGUAGE_CD")				 
					DO list4.Insert(lang)

				}
				set rowNum=pRes.Next(.sc)

			}
			set pResponse.languages = list4
			$$$TRACE("Return Status: "_sc _", languages rowNum: " _ pResponse.languages.Count())

		}
 } else {
		$$$TRACE("Failed to execute Query:"_tSQL4)	
 }


 &sql(SELECT MMI_UNIT into :unitNumber from CORPPRV.ADV_PROVIDER where PRVDR_ID = :tPRVDR)
 if SQLCODE = 0
 {
     $$$TRACE("The SQL error code is " _ SQLCODE _ ", unitNumber is "_ unitNumber)
     set pResponse.unitNumber = unitNumber
 }
 return tSC
